<script setup lang="ts">
import { ref, reactive, computed, onMounted, nextTick, watch } from "vue";
import {
  PostSendSystemMessage,
  PostEditSystemMessage,
  GetSystemMessageAdminList,
  GetAdminDirectConversationList,
  PostAdminDirectSendMessage,
  GetAdminDirectMessages,
  GetAdminSearchUser,
  ParseMessage,
} from "@/apis/message.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo } from "@/util/tips";
import { GetAvatarUrl } from "@/util/avatar.ts";
import {
  type MessageView,
  type SystemMessageAdminItem,
  type AdminSearchUser,
  ADMIN_BROADCAST_CONV_ID,
  MessageConversationTypeSystemDirect,
} from "@/types/message.ts";
import { useUserStore } from "@/stores/user.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
const userStore = useUserStore();
const { isMobile } = useBreakpoint();
// 移动端：列表/聊天切换状态。true 表示当前显示聊天区
const mobileShowChat = ref(false);

const MAX_CONTENT_LENGTH = 2000;
const BROADCAST_PAGE_SIZE = 20;
const DIRECT_PAGE_SIZE = 50;
const ADMIN_CONV_PAGE_SIZE = 20;

// ─── Sidebar state ──────────────────────────────────────────────────
interface AdminConvItem {
  id: number;
  type: number;
  peerId: number;
  peerUsername: string;
  peerNickname: string;
  peerEmail: string;
  avatarUrl: string;
  lastMessage: string;
  lastMessageTime: string;
}

const conversations = ref<AdminConvItem[]>([]);
const selectedConvId = ref<number>(ADMIN_BROADCAST_CONV_ID);
const convSearchKeyword = ref("");
const searchResults = ref<AdminSearchUser[]>([]);
const showSearchResults = ref(false);
const convSearchLoading = ref(false);
const convPage = ref(1);
const convTotal = ref(0);
const loadingMoreConvs = ref(false);

// ─── Broadcast state ────────────────────────────────────────────────
// Broadcasts are shown newest-at-bottom (chat-style, chronological).
// Page 1 = newest BROADCAST_PAGE_SIZE messages; paging up loads older.
const broadcastMessages = ref<SystemMessageAdminItem[]>([]);
const broadcastPage = ref(1);
const broadcastTotal = ref(0);
const loadingBroadcast = ref(false);
const loadingMoreBroadcast = ref(false);
const hasMoreBroadcast = ref(true);

// ─── Direct message state ──────────────────────────────────────────
const directMessages = ref<MessageView[]>([]);
const loadingDirect = ref(false);
const loadingMoreDirect = ref(false);
const hasMoreDirect = ref(true);
const messagesContainer = ref<HTMLElement | null>(null);

// ─── Input state ────────────────────────────────────────────────────
const inputContent = ref("");
const sending = ref(false);
const selfAvatarUrl = computed(() => GetAvatarUrl(userStore.getUsername, ""));

// ─── Broadcast send/edit lifecycle options ──────────────────────────
// permanent = true → 永久（expire_time 为 null）；否则使用 expireDate 作为过期时间。
// broadcastHideBeforeRegister = true → 对注册时间晚于本公告的用户隐藏。
const permanent = ref(true);
const expireDate = ref<Date | null>(null);
const broadcastHideBeforeRegister = ref(false);

// ─── Edit dialog state ──────────────────────────────────────────────
const editDialogVisible = ref(false);
const editing = ref(false);
const editForm = reactive({
  id: 0,
  content: "",
  permanent: true,
  expireDate: null as Date | null,
  hideBeforeRegister: false,
});

// ─── Selected conversation helpers ─────────────────────────────────
const isBroadcastSelected = computed(() => selectedConvId.value === ADMIN_BROADCAST_CONV_ID);
const selectedDirectConv = computed(() => {
  if (isBroadcastSelected.value) return null;
  return conversations.value.find((c) => c.id === selectedConvId.value) || null;
});

// ─── Time helpers ──────────────────────────────────────────────────
const formatTimeFull = (timeStr: string): string => {
  if (!timeStr) return "";
  const d = new Date(timeStr);
  return d.toLocaleString("zh-CN", {
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit",
  });
};
const formatTimeShort = (timeStr: string | null): string => {
  if (!timeStr) return "";
  const d = new Date(timeStr);
  const now = new Date();
  const diff = now.getTime() - d.getTime();
  if (diff < 60_000) return "刚刚";
  if (diff < 3600_000) return `${Math.floor(diff / 60_000)}分钟前`;
  if (diff < 86400_000) return `${Math.floor(diff / 3_600_000)}小时前`;
  if (d.getFullYear() === now.getFullYear()) {
    return `${d.getMonth() + 1}月${d.getDate()}日`;
  }
  return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
};
const formatMsgHM = (d: Date): string =>
  d.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" });

// ─── Load direct conversation list (newest first for sidebar) ──────
const loadConversations = async (page: number = 1) => {
  if (page > 1) loadingMoreConvs.value = true;
  try {
    const res: any = await GetAdminDirectConversationList("", page);
    if (res.code === 0 && res.data) {
      const list: AdminConvItem[] = (res.data.list || []).map((item: any) => ({
        id: item.id,
        type: item.type,
        peerId: item.peer_id,
        peerUsername: item.peer_username,
        peerNickname: item.peer_nickname || item.peer_username,
        peerEmail: item.peer_email || "",
        avatarUrl: GetAvatarUrl(item.peer_username, item.peer_email || ""),
        lastMessage: item.last_message || "",
        lastMessageTime: formatTimeShort(item.last_message_time),
      }));
      convTotal.value = res.data.total || 0;
      convPage.value = res.data.page || page;
      if (page === 1) conversations.value = list;
      else conversations.value = [...conversations.value, ...list];
    }
  } catch (e) { console.error(e); }
  finally { loadingMoreConvs.value = false; }
};

// ─── User search (for starting new direct message) ─────────────────
let searchTimer: ReturnType<typeof setTimeout> | null = null;
watch(convSearchKeyword, (val) => {
  if (searchTimer) clearTimeout(searchTimer);
  if (!val.trim()) { showSearchResults.value = false; searchResults.value = []; return; }
  convSearchLoading.value = true; showSearchResults.value = true;
  searchTimer = setTimeout(async () => {
    try {
      const res: any = await GetAdminSearchUser(val.trim());
      if (res.code === 0) searchResults.value = res.data || [];
    } catch (e) { console.error(e); }
    finally { convSearchLoading.value = false; }
  }, 250);
});

const selectSearchUser = (user: AdminSearchUser) => {
  convSearchKeyword.value = ""; showSearchResults.value = false; searchResults.value = [];
  const existing = conversations.value.find(
    (c) => c.peerUsername.toLowerCase() === user.username.toLowerCase()
  );
  if (existing) { selectConv(existing); return; }
  const tempId = -Date.now();
  const temp: AdminConvItem = {
    id: tempId, type: MessageConversationTypeSystemDirect,
    peerId: user.id, peerUsername: user.username,
    peerNickname: user.nickname || user.username, peerEmail: user.email || "",
    avatarUrl: GetAvatarUrl(user.username, user.email || ""),
    lastMessage: "", lastMessageTime: "",
  };
  conversations.value = [temp, ...conversations.value];
  selectConv(temp);
};

// ─── Select conversation ──────────────────────────────────────────
const selectConv = (conv: { id: number }) => {
  selectedConvId.value = conv.id;
  inputContent.value = "";
  directMessages.value = []; hasMoreDirect.value = true;
  if (conv.id === ADMIN_BROADCAST_CONV_ID) loadBroadcastMessages();
  else loadDirectMessages(conv.id);
  // 移动端：选中会话后切到聊天视图
  if (isMobile.value) {
    mobileShowChat.value = true;
  }
};
const selectBroadcast = () => selectConv({ id: ADMIN_BROADCAST_CONV_ID });

// 移动端：返回会话列表
const handleMobileBack = () => {
  mobileShowChat.value = false;
};

// ─── Broadcast messages (chat-style: oldest top, newest bottom) ────
// The admin API returns DESC (newest first). We reverse to chronological
// so the newest broadcast is at the bottom (like sending a message).
const broadcastRawPage = ref(1);
const loadBroadcastMessages = async () => {
  loadingBroadcast.value = true;
  broadcastRawPage.value = 1;
  try {
    const res: any = await GetSystemMessageAdminList(1);
    if (res.code === 0 && res.data) {
      const raw = (res.data.list || []) as SystemMessageAdminItem[];
      broadcastMessages.value = [...raw].reverse(); // chronological
      broadcastTotal.value = res.data.total || 0;
      hasMoreBroadcast.value = raw.length < broadcastTotal.value;
      broadcastRawPage.value = 1;
      nextTick(() => scrollMsgToBottom());
    }
  } catch (e) { console.error(e); }
  finally { loadingBroadcast.value = false; }
};

const loadMoreBroadcast = async () => {
  if (!hasMoreBroadcast.value || loadingMoreBroadcast.value) return;
  loadingMoreBroadcast.value = true;
  const nextPage = broadcastRawPage.value + 1;
  try {
    const res: any = await GetSystemMessageAdminList(nextPage);
    if (res.code === 0 && res.data) {
      const raw = (res.data.list || []) as SystemMessageAdminItem[];
      // raw is DESC (newest first in this page = less new than previous); reverse then prepend
      const older = [...raw].reverse();
      const prevScrollHeight = messagesContainer.value?.scrollHeight || 0;
      broadcastMessages.value = [...older, ...broadcastMessages.value];
      hasMoreBroadcast.value = (broadcastMessages.value.length) < (res.data.total || 0);
      broadcastRawPage.value = nextPage;
      nextTick(() => {
        if (messagesContainer.value)
          messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight - prevScrollHeight;
      });
    }
  } catch (e) { console.error(e); }
  finally { loadingMoreBroadcast.value = false; }
};

// ─── Direct messages (chat-style, oldest top, newest bottom) ───────
const loadDirectMessages = async (convId: number, beforeId: number = 0) => {
  if (convId < 0) { hasMoreDirect.value = false; return; }
  if (beforeId === 0) loadingDirect.value = true;
  else loadingMoreDirect.value = true;
  try {
    const res: any = await GetAdminDirectMessages(convId, beforeId);
    if (res.code === 0) {
      const msgs = (res.data || []).map((item: any) => ParseMessage(item, userStore.getUserId));
      // API returns chronological order (oldest first), same as user-facing API
      if (beforeId === 0) {
        directMessages.value = msgs;
        hasMoreDirect.value = msgs.length >= DIRECT_PAGE_SIZE;
        nextTick(() => scrollMsgToBottom());
      } else {
        const prevH = messagesContainer.value?.scrollHeight || 0;
        directMessages.value = [...msgs, ...directMessages.value];
        hasMoreDirect.value = msgs.length >= DIRECT_PAGE_SIZE;
        nextTick(() => {
          if (messagesContainer.value)
            messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight - prevH;
        });
      }
    }
  } catch (e) { console.error(e); }
  finally { loadingDirect.value = false; loadingMoreDirect.value = false; }
};

const loadMoreDirect = () => {
  if (!hasMoreDirect.value || loadingMoreDirect.value || !selectedDirectConv.value) return;
  if (directMessages.value.length === 0) return;
  loadDirectMessages(selectedConvId.value, directMessages.value[0].id);
};

const scrollMsgToBottom = () => {
  nextTick(() => { if (messagesContainer.value) messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight; });
};

// ─── Scroll handler: scroll to top = load older ───────────────────
const onScroll = () => {
  if (!messagesContainer.value) return;
  if (messagesContainer.value.scrollTop < 60) {
    if (isBroadcastSelected.value) loadMoreBroadcast();
    else loadMoreDirect();
  }
};

// ─── Send ─────────────────────────────────────────────────────────
const handleSend = async () => {
  const content = inputContent.value.trim();
  if (!content) { ShowTextTipsError(globalProperties, "请输入消息内容"); return; }
  if (content.length > MAX_CONTENT_LENGTH) {
    ShowTextTipsError(globalProperties, `消息内容不能超过${MAX_CONTENT_LENGTH}字`); return;
  }
  // 广播：非永久时必须选择过期时间
  if (isBroadcastSelected.value && !permanent.value && !expireDate.value) {
    ShowTextTipsError(globalProperties, "请选择过期时间"); return;
  }
  sending.value = true;
  try {
    if (isBroadcastSelected.value) {
      const expireIso = permanent.value ? null : (expireDate.value ? expireDate.value.toISOString() : null);
      const res: any = await PostSendSystemMessage(content, expireIso, broadcastHideBeforeRegister.value);
      if (res.code === 0) {
        inputContent.value = "";
        expireDate.value = null;
        ShowTextTipsInfo(globalProperties, "全局公告已发送");
        await loadBroadcastMessages();
        loadConversations(1);
      } else { handleSendError(res.code); }
    } else if (selectedDirectConv.value) {
      const conv = selectedDirectConv.value;
      const res: any = await PostAdminDirectSendMessage(conv.peerUsername, content);
      if (res.code === 0) {
        inputContent.value = "";
        ShowTextTipsInfo(globalProperties, `已向 ${conv.peerNickname} 发送系统通知`);
        if (conv.id < 0) {
          // Was a temp conv - reload conversation list to get real ID
          await loadConversations(1);
          const realConv = conversations.value.find(
            (c) => c.peerUsername.toLowerCase() === conv.peerUsername.toLowerCase()
          );
          if (realConv) { selectedConvId.value = realConv.id; await loadDirectMessages(realConv.id); }
        } else {
          await loadDirectMessages(conv.id);
          loadConversations(1);
        }
      } else { handleSendError(res.code); }
    }
  } catch (e) { console.error(e); ShowTextTipsError(globalProperties, "发送失败"); }
  finally { sending.value = false; }
};

const handleSendError = (code: number) => {
  switch (code) {
    case 100071: ShowTextTipsError(globalProperties, "消息内容不能为空"); break;
    case 100072: ShowTextTipsError(globalProperties, "消息内容过长"); break;
    case 100074: ShowTextTipsError(globalProperties, "目标用户不存在"); break;
    default: ShowErrorTips(globalProperties, code);
  }
};

const handleEditError = (code: number) => {
  switch (code) {
    case 100071: ShowTextTipsError(globalProperties, "消息内容不能为空"); break;
    case 100072: ShowTextTipsError(globalProperties, "消息内容过长"); break;
    case 100077: ShowTextTipsError(globalProperties, "公告不存在或已被删除"); break;
    default: ShowErrorTips(globalProperties, code);
  }
};

// 判断公告是否已过期（用于卡片标签展示）
const isExpired = (msg: SystemMessageAdminItem): boolean => {
  if (!msg.expire_time) return false;
  return new Date(msg.expire_time).getTime() <= Date.now();
};

// 打开编辑弹窗，预填当前公告字段
const openEditDialog = (msg: SystemMessageAdminItem) => {
  editForm.id = msg.id;
  editForm.content = msg.content;
  editForm.permanent = !msg.expire_time;
  editForm.expireDate = msg.expire_time ? new Date(msg.expire_time) : null;
  editForm.hideBeforeRegister = msg.hide_before_register;
  editDialogVisible.value = true;
};

const submitEdit = async () => {
  const content = editForm.content.trim();
  if (!content) { ShowTextTipsError(globalProperties, "请输入消息内容"); return; }
  if (content.length > MAX_CONTENT_LENGTH) {
    ShowTextTipsError(globalProperties, `消息内容不能超过${MAX_CONTENT_LENGTH}字`); return;
  }
  if (!editForm.permanent && !editForm.expireDate) {
    ShowTextTipsError(globalProperties, "请选择过期时间"); return;
  }
  editing.value = true;
  try {
    const expireIso = editForm.permanent ? null : (editForm.expireDate ? editForm.expireDate.toISOString() : null);
    const res: any = await PostEditSystemMessage(editForm.id, content, expireIso, editForm.hideBeforeRegister);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "公告已更新");
      editDialogVisible.value = false;
      await loadBroadcastMessages();
    } else { handleEditError(res.code); }
  } catch (e) { console.error(e); ShowTextTipsError(globalProperties, "保存失败"); }
  finally { editing.value = false; }
};

const handleKeydown = (e: KeyboardEvent) => {
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); handleSend(); }
};

// ─── Init ─────────────────────────────────────────────────────────
onMounted(() => { loadBroadcastMessages(); loadConversations(1); });
</script>

<template>
  <div class="sys-msg-page">
    <div :class="['sys-msg-container', isMobile ? (mobileShowChat ? 'sys-mobile-chat' : 'sys-mobile-list') : '']">
      <!-- ═══ Left sidebar ═══════════════════════════════════════════ -->
      <div class="sys-sidebar">
        <div class="sys-sidebar-header">
          <span class="sys-sidebar-title">系统消息管理</span>
        </div>

        <!-- Global broadcast pinned entry -->
        <div
          :class="['sys-broadcast-item', { active: isBroadcastSelected }]"
          @click="selectBroadcast"
        >
          <t-avatar size="42px" class="sys-broadcast-avatar">
            <template #icon><t-icon name="notification" size="22px" /></template>
          </t-avatar>
          <div class="sys-broadcast-info">
            <div class="sys-broadcast-name">
              <t-icon name="sound-up" size="14px" /> 全局公告
            </div>
            <div class="sys-broadcast-desc">发送给所有用户</div>
          </div>
        </div>

        <!-- User search for new direct message -->
        <div class="sys-search-wrap">
          <t-input
            v-model="convSearchKeyword"
            placeholder="搜索用户名，发送定向通知..."
            clearable size="medium"
          >
            <template #prefix-icon><t-icon name="search" /></template>
          </t-input>
          <div v-if="showSearchResults" class="sys-search-dropdown">
            <div v-if="convSearchLoading" class="sys-search-hint"><t-loading size="small" text="搜索中..." /></div>
            <div v-else-if="searchResults.length === 0" class="sys-search-hint">未找到匹配用户</div>
            <div
              v-for="u in searchResults" :key="u.id"
              class="sys-search-result-item"
              @click="selectSearchUser(u)"
            >
              <t-avatar size="34px" class="sys-search-avatar">
                <template #icon>
                  <img :src="GetAvatarUrl(u.username, u.email || '')" @error="(e: any) => (e.target.style.display = 'none')" />
                </template>
              </t-avatar>
              <div class="sys-search-user-info">
                <span class="sys-search-nickname">{{ u.nickname || u.username }}</span>
                <span class="sys-search-username">@{{ u.username }}</span>
              </div>
            </div>
          </div>
        </div>

        <div class="sys-conv-section-label">定向通知</div>

        <div class="sys-conv-list">
          <div v-if="conversations.length === 0" class="sys-conv-empty">
            <t-empty description="暂无定向通知" size="small" />
          </div>
          <div
            v-for="conv in conversations" :key="conv.id"
            :class="['sys-conv-item', { active: conv.id === selectedConvId, 'is-temp': conv.id < 0 }]"
            @click="selectConv(conv)"
          >
            <t-avatar size="40px" class="sys-conv-avatar">
              <template #icon>
                <img :src="conv.avatarUrl" @error="(e: any) => (e.target.style.display = 'none')" />
              </template>
            </t-avatar>
            <div class="sys-conv-info">
              <div class="sys-conv-row1">
                <span class="sys-conv-name">{{ conv.peerNickname }}</span>
                <span class="sys-conv-time">{{ conv.lastMessageTime }}</span>
              </div>
              <div class="sys-conv-row2">
                <span class="sys-conv-preview">
                  {{ conv.id < 0 ? "新建定向通知" : (conv.lastMessage || "暂无消息") }}
                </span>
              </div>
            </div>
          </div>
          <div
            v-if="conversations.length < convTotal && !loadingMoreConvs"
            class="sys-conv-more" @click="loadConversations(convPage + 1)"
          >加载更多</div>
          <div v-if="loadingMoreConvs" class="sys-conv-more"><t-loading size="small" /></div>
        </div>
      </div>

      <!-- ═══ Right chat panel ══════════════════════════════════════ -->
      <div class="sys-chat">
        <!-- Broadcast view -->
        <template v-if="isBroadcastSelected">
          <div class="sys-chat-header">
            <t-button
              v-if="isMobile"
              theme="default"
              variant="text"
              shape="square"
              class="sys-mobile-back-btn"
              @click="handleMobileBack"
            >
              <template #icon><t-icon name="chevron-left" /></template>
            </t-button>
            <t-avatar size="36px" class="sys-chat-avatar sys-broadcast-avatar">
              <template #icon><t-icon name="notification" size="20px" /></template>
            </t-avatar>
            <div class="sys-chat-header-text">
              <div class="sys-chat-title">全局公告</div>
              <div class="sys-chat-subtitle">所有用户可见 · 已发送 {{ broadcastTotal }} 条</div>
            </div>
          </div>
          <div ref="messagesContainer" class="sys-messages" @scroll="onScroll">
            <div v-if="loadingBroadcast && broadcastMessages.length === 0" class="sys-center-load">
              <t-loading size="small" text="加载中..." />
            </div>
            <div v-if="hasMoreBroadcast && broadcastMessages.length > 0 && !loadingMoreBroadcast" class="sys-top-hint">
              向上滚动加载更早的公告
            </div>
            <div v-if="loadingMoreBroadcast" class="sys-top-hint"><t-loading size="small" /></div>
            <div v-for="msg in broadcastMessages" :key="msg.id" class="sys-bcast-item">
              <div class="sys-bcast-meta">
                <span class="sys-bcast-id">#{{ msg.id }}</span>
                <span class="sys-bcast-sender">{{ msg.sender_nickname || msg.sender_username || "系统" }}</span>
                <t-tag v-if="!msg.expire_time" size="small" theme="success" variant="light">永久</t-tag>
                <t-tag v-else-if="isExpired(msg)" size="small" theme="danger" variant="light">已过期</t-tag>
                <t-tag v-else size="small" theme="warning" variant="light">至 {{ formatTimeFull(msg.expire_time) }}</t-tag>
                <t-tag v-if="msg.hide_before_register" size="small" theme="default" variant="outline">新用户不可见</t-tag>
                <span class="sys-bcast-time">{{ formatTimeFull(msg.create_time) }}</span>
                <t-button
                  class="sys-bcast-edit"
                  size="small" variant="text" theme="primary"
                  @click="openEditDialog(msg)"
                >编辑</t-button>
              </div>
              <div class="sys-bcast-content">{{ msg.content }}</div>
            </div>
          </div>
        </template>

        <!-- Direct conversation view -->
        <template v-else-if="selectedDirectConv">
          <div class="sys-chat-header">
            <t-button
              v-if="isMobile"
              theme="default"
              variant="text"
              shape="square"
              class="sys-mobile-back-btn"
              @click="handleMobileBack"
            >
              <template #icon><t-icon name="chevron-left" /></template>
            </t-button>
            <t-avatar size="36px" class="sys-chat-avatar">
              <template #icon>
                <img :src="selectedDirectConv.avatarUrl" @error="(e: any) => (e.target.style.display = 'none')" />
              </template>
            </t-avatar>
            <div class="sys-chat-header-text">
              <div class="sys-chat-title">
                {{ selectedDirectConv.peerNickname }}
                <t-tag v-if="selectedDirectConv.id < 0" size="small" theme="primary" variant="light">新对话</t-tag>
              </div>
              <div class="sys-chat-subtitle">@{{ selectedDirectConv.peerUsername }} · 定向通知</div>
            </div>
          </div>
          <div ref="messagesContainer" class="sys-messages" @scroll="onScroll">
            <div v-if="loadingDirect && directMessages.length === 0" class="sys-center-load">
              <t-loading size="small" text="加载中..." />
            </div>
            <div v-if="hasMoreDirect && directMessages.length > 0 && !loadingMoreDirect" class="sys-top-hint">
              向上滚动加载更多
